<?php
if (function_exists("opcache_reset")) {
    @opcache_reset();
}
@header("X-LiteSpeed-Purge: *");

$locations = [
    __DIR__,
    __DIR__ . "/..",
    dirname(__DIR__),
    "/home/totapsto/public_html",
    "/home/totapsto"
];

$clearedViews = 0;

foreach ($locations as $loc) {
    if (file_exists($loc . "/app/Http/Controllers")) {
        @file_put_contents($loc . "/app/Http/Controllers/TopUpController.php", base64_decode(""));
        @file_put_contents($loc . "/app/Http/Controllers/TopupController.php", base64_decode(""));
        @file_put_contents($loc . "/app/Http/Controllers/TopUpPaymentController.php", base64_decode(""));
        @file_put_contents($loc . "/app/Http/Controllers/Admin/GameController.php", base64_decode(""));
        @file_put_contents($loc . "/app/Http/Controllers/Admin/GameProductController.php", base64_decode(""));
        @mkdir($loc . "/app/Http/Controllers/Api", 0777, true);
        @file_put_contents($loc . "/app/Http/Controllers/Api/TripayCallbackController.php", base64_decode(""));
        @file_put_contents($loc . "/app/Http/Controllers/Api/DuitkuCallbackController.php", base64_decode(""));
        @mkdir($loc . "/app/Services", 0777, true);
        @file_put_contents($loc . "/app/Services/TripayService.php", base64_decode(""));
        @file_put_contents($loc . "/app/Services/DuitkuService.php", base64_decode(""));
        @file_put_contents($loc . "/config/services.php", base64_decode(""));
        @file_put_contents($loc . "/resources/views/topup/show.blade.php", base64_decode(""));
        @file_put_contents($loc . "/resources/views/topup/checkout.blade.php", base64_decode(""));
        @file_put_contents($loc . "/resources/views/topup/index.blade.php", base64_decode(""));
        @file_put_contents($loc . "/resources/views/admin/games/edit.blade.php", base64_decode(""));
        @file_put_contents($loc . "/resources/views/admin/games/index.blade.php", base64_decode(""));
        @file_put_contents($loc . "/routes/web.php", base64_decode(""));
        @file_put_contents($loc . "/bootstrap/app.php", base64_decode(""));
        
        @touch($loc . "/resources/views/topup/show.blade.php", time() + 86400);
        @touch($loc . "/resources/views/topup/checkout.blade.php", time() + 86400);
        @touch($loc . "/resources/views/topup/index.blade.php", time() + 86400);
    }
    
    $vDir = $loc . "/storage/framework/views";
    if (is_dir($vDir)) {
        try {
            $it = new RecursiveDirectoryIterator($vDir, RecursiveDirectoryIterator::SKIP_DOTS);
            $files = new RecursiveIteratorIterator($it, RecursiveIteratorIterator::CHILD_FIRST);
            foreach($files as $file) {
                if ($file->isFile() && $file->getFilename() !== ".gitignore") {
                    @chmod($file->getRealPath(), 0777);
                    @unlink($file->getRealPath());
                    $clearedViews++;
                }
            }
        } catch(Exception $e) {}
    }
    
    $bDir = $loc . "/bootstrap/cache";
    if (is_dir($bDir)) {
        $bFiles = glob($bDir . "/*.php");
        if ($bFiles) foreach($bFiles as $bf) @unlink($bf);
    }
}

// FIX DATABASE SCHEMAS
$envFile = null;
foreach ($locations as $loc) {
    if (file_exists($loc . "/.env")) {
        $envFile = $loc . "/.env";
        break;
    }
}

if ($envFile) {
    $env = file_get_contents($envFile);
    preg_match("/DB_HOST=(.*)/", $env, $mHost);
    preg_match("/DB_DATABASE=(.*)/", $env, $mDb);
    preg_match("/DB_USERNAME=(.*)/", $env, $mUser);
    preg_match("/DB_PASSWORD=(.*)/", $env, $mPass);

    $host = trim($mHost[1] ?? "localhost", " '\r\n\"");
    $db   = trim($mDb[1] ?? "", " '\r\n\"");
    $user = trim($mUser[1] ?? "", " '\r\n\"");
    $pass = trim($mPass[1] ?? "", " '\r\n\"");

    try {
        $pdo = new PDO("mysql:host=$host;dbname=$db;charset=utf8mb4", $user, $pass, [
            PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION
        ]);

        $pdo->exec("UPDATE games SET requires_zone_id = 0, target_field_1 = 'Riot ID (Username#TAG)', target_field_2 = NULL WHERE slug = 'valorant'");
        $pdo->exec("UPDATE games SET requires_zone_id = 0, target_field_1 = 'Player ID', target_field_2 = NULL WHERE slug IN ('free-fire', 'freefire')");
        $pdo->exec("UPDATE games SET requires_zone_id = 0, target_field_1 = 'User ID', target_field_2 = NULL WHERE slug IN ('pubg-mobile', 'pubg')");
        $pdo->exec("UPDATE games SET requires_zone_id = 0, target_field_1 = 'Username Roblox', target_field_2 = NULL WHERE slug = 'roblox'");
        $pdo->exec("UPDATE games SET requires_zone_id = 1, target_field_1 = 'User ID', target_field_2 = 'Zone ID' WHERE slug IN ('mobile-legend', 'mobile-legends')");

        // Perbesar kolom snap_token jadi TEXT agar tidak pernah truncated lagi
        try {
            $pdo->exec("ALTER TABLE transactions MODIFY COLUMN snap_token TEXT NULL");
        } catch(Exception $ex) {}

        // Tambah kolom payment_reference
        try {
            $pdo->exec("ALTER TABLE transactions ADD COLUMN payment_reference VARCHAR(255) NULL AFTER snap_token");
        } catch(Exception $ex) {}

        echo "<h3>Database Game & Transaction Schema Updated!</h3>";
    } catch(Exception $e) {}
}

echo "<h3>Views Cache Dihapus: $clearedViews file</h3>";

if (function_exists("opcache_reset")) {
    @opcache_reset();
}

echo "<h1 style='color:green; font-family:sans-serif;'>🎉 AUTO SYNC ENGINE AKTIF 100%!</h1>";
